class Inventory {
  constructor() {
    this.items = {};
  }

  add(name, qty) {
    if (this.items[name]) {
      this.items[name] += qty;
    } else {
      this.items[name] = qty;
    }
  }

  remove(name, qty) {
    if (!this.items[name] || this.items[name] < qty) {
      throw new Error("Not enough stock to remove");
    }
    this.items[name] -= qty;
  }

  count(name) {
    return this.items[name] || 0;
  }
}

